-- NIL Intelligence Network: full deploy bundle. Generated by scripts/bundle-sql.mjs. Run once on an empty database.
begin;
create table if not exists schema_migrations (name text primary key, applied_at timestamptz not null default now());

-- ===== 0001_schema.sql
-- NIL Intelligence Network: single source of truth
-- Target: Supabase (Postgres 15+). Validated locally on PGlite.
-- Principle: a rule is a row, never a sentence on a page. Pages render from rule versions.

-- ---------------------------------------------------------------- reference
create table states (
  id            serial primary key,
  code          char(2) not null unique,
  name          text not null unique,
  slug          text not null unique
);

-- Anything that issues NIL rules above the school level.
create table governing_bodies (
  id            serial primary key,
  slug          text not null unique,
  name          text not null,
  short_name    text not null,
  body_type     text not null check (body_type in (
                  'federal_agency','national_association','enforcement_body',
                  'state_legislature','state_agency','state_association','conference')),
  state_id      int references states(id),
  parent_id     int references governing_bodies(id),
  website_url   text,
  description   text
);

create table school_districts (
  id            serial primary key,
  slug          text not null unique,
  name          text not null,
  state_id      int not null references states(id),
  county        text,
  website_url   text,
  nces_district_id text
);

-- Colleges and high schools share one table; views `colleges` and `high_schools` split them.
create table institutions (
  id               serial primary key,
  slug             text not null,
  name             text not null,
  short_name       text,
  institution_type text not null check (institution_type in ('college','high_school')),
  sector           text check (sector in ('public','private','charter')),
  state_id         int not null references states(id),
  city             text,
  county           text,
  street_address   text,
  postal_code      text,
  district_id      int references school_districts(id),            -- high schools
  conference_id    int references governing_bodies(id),            -- colleges
  division         text,                                           -- 'NCAA Division I', 'FHSAA member'
  classification   text,                                           -- only when verified
  nces_id          text,
  ipeds_id         text,
  website_url      text,
  athletics_url    text,
  athletics_brand  text,
  profile_source_id int,                                           -- fk added below
  publication_state text not null default 'discovered' check (publication_state in
                   ('discovered','researched','verified','school_confirmed')),
  created_at       timestamptz not null default now(),
  updated_at       timestamptz not null default now(),
  unique (state_id, institution_type, slug)
);

-- Which rule-making bodies an institution answers to (drives the cascade).
create table institution_governing_bodies (
  institution_id    int not null references institutions(id) on delete cascade,
  governing_body_id int not null references governing_bodies(id),
  relationship      text not null default 'member' check (relationship in ('member','subject_to')),
  primary key (institution_id, governing_body_id)
);

create table sports (
  id    serial primary key,
  slug  text not null unique,
  name  text not null
);

create table institution_sports (
  institution_id int not null references institutions(id) on delete cascade,
  sport_id       int not null references sports(id),
  gender         text not null default 'unspecified' check (gender in ('mens','womens','coed','unspecified')),
  season         text,
  source_id      int,
  primary key (institution_id, sport_id, gender)
);

-- ---------------------------------------------------------------- sources
create table sources (
  id               serial primary key,
  slug             text not null unique,
  title            text not null,
  url              text not null,
  organization     text not null,
  governing_body_id int references governing_bodies(id),
  source_type      text not null check (source_type in (
                     'statute','regulation','bylaw','board_document','form','institution_policy',
                     'district_policy','official_faq','official_webpage','government_database',
                     'legislative_record','secondary_reporting')),
  is_primary       boolean not null default true,
  published_on     date,
  published_note   text,          -- when only an approximate/derived date is known
  effective_on     date,
  retrieved_on     date not null,
  archived_url     text,
  content_hash     text,          -- filled by the change monitor
  notes            text
);
alter table institutions add constraint institutions_profile_source_fk
  foreign key (profile_source_id) references sources(id);
alter table institution_sports add constraint institution_sports_source_fk
  foreign key (source_id) references sources(id);

-- ---------------------------------------------------------------- rules
create table rule_categories (
  id         serial primary key,
  slug       text not null unique,
  name       text not null,
  sort_order int not null default 100
);

-- The fixed list of questions every hub can answer.
create table rule_topics (
  id           serial primary key,
  slug         text not null unique,
  category_id  int not null references rule_categories(id),
  label        text not null,        -- short matrix label
  question     text not null,        -- plain-English question
  applies_to   text not null default 'both' check (applies_to in ('high_school','college','both')),
  in_ip_matrix boolean not null default false,
  sort_order   int not null default 100
);

-- One rule = one issuer answering one topic for one audience.
create table rules (
  id                serial primary key,
  slug              text not null unique,
  rule_topic_id     int not null references rule_topics(id),
  scope_type        text not null check (scope_type in ('state','governing_body','district','institution')),
  state_id          int references states(id),
  governing_body_id int references governing_bodies(id),
  district_id       int references school_districts(id),
  institution_id    int references institutions(id),
  applies_to        text not null check (applies_to in ('high_school','college','both')),
  status            text not null default 'active' check (status in ('active','superseded','repealed','pending')),
  created_at        timestamptz not null default now(),
  check (
    (scope_type = 'state'          and state_id is not null and governing_body_id is null and district_id is null and institution_id is null) or
    (scope_type = 'governing_body' and governing_body_id is not null and district_id is null and institution_id is null) or
    (scope_type = 'district'       and district_id is not null and institution_id is null) or
    (scope_type = 'institution'    and institution_id is not null)
  )
);

-- Every change to a rule is a new version; old versions are never edited or deleted.
create table rule_versions (
  id                  serial primary key,
  rule_id             int not null references rules(id) on delete cascade,
  version_no          int not null,
  answer              text not null check (answer in
                        ('yes','yes_with_conditions','only_with_approval','no','not_addressed','unclear')),
  summary             text not null,     -- plain English, one or two sentences
  conditions          text,              -- the "as long as"
  citation            text,              -- e.g. 'FHSAA Bylaw 9.9.4.3'
  effective_date      date,
  effective_note      text,
  end_date            date,
  is_current          boolean not null default true,
  verification_status text not null default 'unverified' check (verification_status in
                        ('unverified','needs_verification','researched','verified','school_confirmed','disputed')),
  last_verified_on    date,
  verified_by         text,
  change_note         text,              -- what changed vs the previous version
  previous_version_id int references rule_versions(id),
  created_at          timestamptz not null default now(),
  unique (rule_id, version_no)
);
create unique index one_current_version_per_rule on rule_versions(rule_id) where is_current;

-- Provenance: which source supports which rule version, and where in it.
create table rule_version_sources (
  id              serial primary key,
  rule_version_id int not null references rule_versions(id) on delete cascade,
  source_id       int not null references sources(id),
  locator         text,           -- section / page
  quote           text,           -- verbatim supporting text
  quote_check     text not null default 'machine_extracted' check (quote_check in
                    ('machine_extracted','machine_confirmed_twice','machine_raw_text','human_checked')),
  checked_on      date not null,
  checked_by      text not null
);
create index rule_version_sources_rv on rule_version_sources(rule_version_id);

-- Structured detail for disclosure rules.
create table disclosure_requirements (
  rule_version_id int primary key references rule_versions(id) on delete cascade,
  what            text not null,
  recipient       text not null,
  deadline_text   text not null,
  deadline_business_days int,
  threshold_usd   numeric,
  form_name       text,
  form_url        text,
  platform_name   text,
  platform_url    text
);

create table prohibited_categories (
  id    serial primary key,
  slug  text not null unique,
  name  text not null
);
create table rule_version_prohibited_categories (
  rule_version_id        int not null references rule_versions(id) on delete cascade,
  prohibited_category_id int not null references prohibited_categories(id),
  wording                text,     -- exact wording in the source
  primary key (rule_version_id, prohibited_category_id)
);

-- Public change history ("Rule updated August 2026 - what changed?").
create table rule_change_log (
  id              serial primary key,
  rule_id         int references rules(id) on delete cascade,
  governing_body_id int references governing_bodies(id),
  state_id        int references states(id),
  changed_on      date not null,
  change_type     text not null check (change_type in ('adopted','amended','on_agenda','ratified','repealed','clarified','correction')),
  summary         text not null,
  source_id       int references sources(id),
  from_version_id int references rule_versions(id),
  to_version_id   int references rule_versions(id),
  is_public       boolean not null default true
);

-- Things that may change the rules soon. Never rendered as current rules.
create table watch_items (
  id              serial primary key,
  slug            text not null unique,
  title           text not null,
  status_text     text not null,
  summary         text not null,
  applies_to      text not null check (applies_to in ('high_school','college','both')),
  state_id        int references states(id),
  governing_body_id int references governing_bodies(id),
  as_of           date not null,
  source_id       int references sources(id),
  is_open         boolean not null default true
);

-- Where sources disagree. A page shows "under review" for any topic with an open high-severity conflict.
create table conflicts (
  id          serial primary key,
  rule_id     int references rules(id) on delete cascade,
  summary     text not null,
  severity    text not null check (severity in ('low','medium','high')),
  status      text not null default 'open' check (status in ('open','resolved')),
  resolution  text,
  opened_on   date not null,
  resolved_on date
);

-- Audit trail of every verification action on anything.
create table verification_events (
  id          serial primary key,
  entity_type text not null check (entity_type in ('rule_version','institution','contact','policy','page','source')),
  entity_id   int not null,
  status      text not null,
  method      text not null check (method in ('automated_fetch','desk_review','second_checker','school_email','school_phone','school_form')),
  verified_on date not null,
  verified_by text not null,
  notes       text
);

-- ---------------------------------------------------------------- school-level
create table school_nil_policies (
  id                  serial primary key,
  institution_id      int not null references institutions(id) on delete cascade,
  title               text not null,
  summary             text not null,
  policy_status       text not null check (policy_status in ('published','none_found','outdated','unconfirmed')),
  source_id           int references sources(id),
  adopted_on          date,
  verification_status text not null default 'needs_verification',
  last_verified_on    date,
  verified_by         text
);

-- Programs and intake paths a school runs for NIL (exchanges, collectives, education).
create table nil_programs (
  id             serial primary key,
  institution_id int not null references institutions(id) on delete cascade,
  name           text not null,
  program_type   text not null check (program_type in ('marketplace','collective','nil_entity','sponsorship_sales','education','in_house_unit','licensing')),
  description    text not null,
  url            text,
  source_id      int references sources(id),
  verification_status text not null default 'needs_verification',
  sort_order     int not null default 100
);

create table school_contacts (
  id             serial primary key,
  institution_id int not null references institutions(id) on delete cascade,
  office         text not null,
  role           text not null,
  person_name    text,
  email          text,
  phone          text,
  url            text,
  is_public      boolean not null default false,   -- only office-level or officially published role contacts
  show_on_page   boolean not null default false,
  source_id      int references sources(id),
  verification_status text not null default 'needs_verification',
  last_verified_on date
);

create table school_confirmations (
  id             serial primary key,
  institution_id int not null references institutions(id) on delete cascade,
  contact_role   text not null,
  method         text not null,
  evidence_ref   text,
  confirmed_on   date not null,
  recheck_on     date
);

-- ---------------------------------------------------------------- guidance content (structured, reusable)
create table scenarios (
  id         serial primary key,
  slug       text not null unique,
  question   text not null,
  applies_to text not null check (applies_to in ('high_school','college','both')),
  sort_order int not null default 100
);
-- role 'governs' decides the outcome; 'condition' adds an "as long as" line.
create table scenario_rule_topics (
  scenario_id   int not null references scenarios(id) on delete cascade,
  rule_topic_id int not null references rule_topics(id),
  role          text not null default 'governs' check (role in ('governs','condition')),
  primary key (scenario_id, rule_topic_id)
);

-- Action-plan steps and parent guidance, written once per issuer and inherited by every school under it.
create table guidance_blocks (
  id                serial primary key,
  slug              text not null unique,
  block_type        text not null check (block_type in ('action_step','parent_guidance')),
  scope_type        text not null check (scope_type in ('state','governing_body','district','institution','level')),
  state_id          int references states(id),
  governing_body_id int references governing_bodies(id),
  institution_id    int references institutions(id),
  applies_to        text not null check (applies_to in ('high_school','college','both')),
  title             text not null,
  body              text not null,
  rule_topic_id     int references rule_topics(id),   -- the rule this step rests on, if any
  link_url          text,
  link_label        text,
  sort_order        int not null default 100
);

-- ---------------------------------------------------------------- local opportunity intelligence (architecture only for now)
create table market_areas (
  id        serial primary key,
  slug      text not null unique,
  name      text not null,
  state_id  int not null references states(id),
  counties  text[]
);
create table institution_market_areas (
  institution_id int not null references institutions(id) on delete cascade,
  market_area_id int not null references market_areas(id),
  primary key (institution_id, market_area_id)
);
create table local_opportunity_intel (
  id             serial primary key,
  market_area_id int references market_areas(id),
  institution_id int references institutions(id),
  intel_type     text not null check (intel_type in ('industry','business_category','seasonal_event','campaign_idea','sport_insight')),
  title          text not null,
  body           text not null,
  sport_id       int references sports(id),
  source_id      int references sources(id),
  verification_status text not null default 'unverified',
  reviewed_by    text,
  reviewed_on    date,
  is_published   boolean not null default false
);

-- ---------------------------------------------------------------- pages, index control, redirects, requests
create table pages (
  id               serial primary key,
  path             text not null unique,          -- canonical path, e.g. /nil/florida/colleges/university-of-florida/
  page_type        text not null check (page_type in
                     ('national_hub','states_index','state_hub','college_directory','high_school_directory',
                      'college_hub','high_school_hub','sports_index','sport_hub','governing_body','methodology','tool')),
  state_id         int references states(id),
  institution_id   int references institutions(id),
  governing_body_id int references governing_bodies(id),
  sport_id         int references sports(id),
  title            text,
  meta_description text,
  h1               text,
  is_discoverable  boolean not null default true,   -- reachable in Find My School / internal nav
  human_approved   boolean not null default false,  -- editorial sign-off; required to index
  approved_by      text,
  approved_on      date,
  index_override   text check (index_override in ('force_noindex')),
  last_updated     date
);

create table redirects (
  from_path text primary key,
  to_path   text not null,
  status    int not null default 301
);

create table school_requests (
  id           serial primary key,
  school_name  text not null,
  state_code   char(2),
  requester_role text,
  email_hash   text,
  created_at   timestamptz not null default now()
);

create table monitors (
  source_id       int primary key references sources(id) on delete cascade,
  frequency       text not null check (frequency in ('daily','weekly','monthly')),
  last_checked_on date,
  last_changed_on date,
  alert_status    text not null default 'ok' check (alert_status in ('ok','changed','unreachable'))
);

insert into schema_migrations (name) values ('0001_schema.sql');

-- ===== 0002_views.sql
-- Convenience splits
create view colleges as select * from institutions where institution_type = 'college';
create view high_schools as select * from institutions where institution_type = 'high_school';
create view athletic_conferences as select * from governing_bodies where body_type = 'conference';

-- THE CASCADE: every current rule that applies to an institution, from every layer above it.
-- Change one statewide rule version and every school under it inherits the change.
create view v_institution_rules as
select
  i.id                as institution_id,
  r.id                as rule_id,
  r.slug              as rule_slug,
  r.scope_type,
  case r.scope_type when 'state' then 1 when 'governing_body' then 2 when 'district' then 3 else 4 end as layer_order,
  coalesce(gb.short_name, st.name || ' law', d.name, i.short_name, i.name) as issuer_name,
  gb.slug             as governing_body_slug,
  t.id                as rule_topic_id,
  t.slug              as topic_slug,
  t.label             as topic_label,
  t.question          as topic_question,
  t.in_ip_matrix,
  t.sort_order        as topic_sort,
  c.slug              as category_slug,
  c.name              as category_name,
  c.sort_order        as category_sort,
  v.id                as rule_version_id,
  v.version_no,
  v.answer,
  v.summary,
  v.conditions,
  v.citation,
  v.effective_date,
  v.effective_note,
  v.verification_status,
  v.last_verified_on,
  v.verified_by
from institutions i
join rules r on r.status = 'active'
  and (r.applies_to = 'both' or r.applies_to = i.institution_type)
  and (
       (r.scope_type = 'state' and r.state_id = i.state_id)
    or (r.scope_type = 'governing_body' and (
          r.governing_body_id = i.conference_id
          or exists (select 1 from institution_governing_bodies igb
                     where igb.institution_id = i.id and igb.governing_body_id = r.governing_body_id)))
    or (r.scope_type = 'district' and r.district_id = i.district_id)
    or (r.scope_type = 'institution' and r.institution_id = i.id)
  )
join rule_versions v on v.rule_id = r.id and v.is_current
join rule_topics t on t.id = r.rule_topic_id
join rule_categories c on c.id = t.category_id
left join governing_bodies gb on gb.id = r.governing_body_id
left join states st on st.id = r.state_id and r.scope_type = 'state'
left join school_districts d on d.id = r.district_id and r.scope_type = 'district';

-- Same cascade at state level (rules every school of that level in the state inherits).
create view v_state_rules as
select
  s.id as state_id, lvl.level,
  r.id as rule_id, r.slug as rule_slug, r.scope_type,
  case r.scope_type when 'state' then 1 else 2 end as layer_order,
  coalesce(gb.short_name, s.name || ' law') as issuer_name,
  gb.slug as governing_body_slug,
  t.id as rule_topic_id, t.slug as topic_slug, t.label as topic_label, t.question as topic_question,
  t.in_ip_matrix, t.sort_order as topic_sort,
  c.slug as category_slug, c.name as category_name, c.sort_order as category_sort,
  v.id as rule_version_id, v.version_no, v.answer, v.summary, v.conditions, v.citation,
  v.effective_date, v.effective_note, v.verification_status, v.last_verified_on, v.verified_by
from states s
cross join (values ('high_school'), ('college')) as lvl(level)
join rules r on r.status = 'active'
  and (r.applies_to = 'both' or r.applies_to = lvl.level)
  and (
       (r.scope_type = 'state' and r.state_id = s.id)
    or (r.scope_type = 'governing_body' and exists (
          select 1 from governing_bodies g
          where g.id = r.governing_body_id
            and g.body_type <> 'conference'
            and (g.state_id = s.id or g.state_id is null)))
  )
join rule_versions v on v.rule_id = r.id and v.is_current
join rule_topics t on t.id = r.rule_topic_id
join rule_categories c on c.id = t.category_id
left join governing_bodies gb on gb.id = r.governing_body_id;

-- INDEX QUALITY GATE for school hubs. A page is indexable only when every check passes.
-- No word counts. Every check is about verified, school-relevant utility.
create view v_page_quality_gate as
with ir as (
  select * from v_institution_rules
),
agg as (
  select
    i.id as institution_id,
    exists (select 1 from institution_governing_bodies g where g.institution_id = i.id) as governing_body_identified,
    exists (select 1 from ir where ir.institution_id = i.id and ir.topic_slug = 'nil-allowed') as current_status_established,
    (select count(*) from ir where ir.institution_id = i.id) as rule_count,
    (select count(*) from ir where ir.institution_id = i.id
        and ir.verification_status not in ('verified','school_confirmed')) as rules_not_verified,
    (select count(*) from ir where ir.institution_id = i.id
        and not exists (select 1 from rule_version_sources rs join sources s on s.id = rs.source_id
                        where rs.rule_version_id = ir.rule_version_id and s.is_primary)) as rules_without_primary_source,
    (select count(distinct ir.topic_slug) from ir where ir.institution_id = i.id and ir.answer <> 'not_addressed') as topics_answered,
    (select count(*) from ir where ir.institution_id = i.id and ir.scope_type in ('district','institution')
        and ir.answer <> 'not_addressed') as school_level_rules,
    exists (select 1 from school_nil_policies p where p.institution_id = i.id) as school_policy_checked,
    exists (select 1 from school_nil_policies p where p.institution_id = i.id and p.policy_status = 'published') as school_policy_published,
    (select count(*) from nil_programs n where n.institution_id = i.id) as program_count,
    exists (select 1 from school_contacts c where c.institution_id = i.id and c.show_on_page
              and c.verification_status in ('verified','school_confirmed')) as contact_verified,
    (select count(*) from scenarios sc
       where (sc.applies_to = 'both' or sc.applies_to = i.institution_type)
         and not exists (select 1 from scenario_rule_topics srt
                         where srt.scenario_id = sc.id and srt.role = 'governs'
                           and not exists (select 1 from ir where ir.institution_id = i.id
                                           and ir.rule_topic_id = srt.rule_topic_id and ir.answer <> 'not_addressed'))) as scenarios_answered,
    (select max(ir.last_verified_on) from ir where ir.institution_id = i.id) as last_verified_on,
    exists (select 1 from conflicts cf join ir on ir.rule_id = cf.rule_id
            where ir.institution_id = i.id and cf.status = 'open' and cf.severity = 'high') as open_high_conflict
  from institutions i
)
select
  p.id as page_id, p.path, p.page_type, a.*,
  (p.title is not null and p.meta_description is not null and p.h1 is not null) as meta_complete,
  p.human_approved,
  -- individual checks
  a.governing_body_identified                          as chk_governing_body,
  a.current_status_established                         as chk_current_status,
  (a.rule_count > 0 and a.rules_not_verified = 0)      as chk_rules_verified,
  (a.rule_count > 0 and a.rules_without_primary_source = 0) as chk_sources_attached,
  (a.topics_answered >= 8)                             as chk_matrix_populated,
  a.school_policy_checked                              as chk_school_info_checked,
  -- duplicate/thin-content guard: the page must hold facts the state hub does not
  ((a.school_level_rules + a.program_count + case when a.school_policy_published then 1 else 0 end) >= 3) as chk_school_specific_value,
  a.contact_verified                                   as chk_contact_checked,
  (a.scenarios_answered >= 5)                          as chk_scenarios_answered,
  (a.last_verified_on is not null)                     as chk_last_verified,
  (not a.open_high_conflict)                           as chk_no_open_conflict,
  case when
        a.governing_body_identified and a.current_status_established
    and a.rule_count > 0 and a.rules_not_verified = 0 and a.rules_without_primary_source = 0
    and a.topics_answered >= 8 and a.school_policy_checked
    and (a.school_level_rules + a.program_count + case when a.school_policy_published then 1 else 0 end) >= 3
    and a.contact_verified and a.scenarios_answered >= 5 and a.last_verified_on is not null
    and not a.open_high_conflict
    and p.title is not null and p.meta_description is not null and p.h1 is not null
    and p.human_approved and p.index_override is null
  then 'index' else 'noindex' end as index_status
from pages p
join agg a on a.institution_id = p.institution_id
where p.page_type in ('college_hub','high_school_hub');

insert into schema_migrations (name) values ('0002_views.sql');

-- ===== 0003_security.sql
-- Access control. Default deny.
-- The site is generated at build time over a server-side Postgres connection (DATABASE_URL, stored only in the build environment).
-- Nothing in the browser talks to the database, so the public API roles get no access at all.
-- When a public feature needs data (for example Find My School), it gets its own narrow read-only policy in a later migration.

-- 1. Row Level Security on every table in the public schema, with no policies = no rows for anon / authenticated.
do $$
declare t record;
begin
  for t in select tablename from pg_tables where schemaname = 'public' loop
    execute format('alter table public.%I enable row level security', t.tablename);
  end loop;
end $$;

-- 2. Views run with the caller's rights, so they cannot be used to read around RLS.
alter view colleges set (security_invoker = true);
alter view high_schools set (security_invoker = true);
alter view athletic_conferences set (security_invoker = true);
alter view v_institution_rules set (security_invoker = true);
alter view v_state_rules set (security_invoker = true);
alter view v_page_quality_gate set (security_invoker = true);

-- 3. Belt and braces on Supabase: strip table privileges from the public API roles (skipped where those roles do not exist).
do $$
begin
  if exists (select 1 from pg_roles where rolname = 'anon') then
    revoke all on all tables in schema public from anon;
    revoke all on all sequences in schema public from anon;
    alter default privileges in schema public revoke all on tables from anon;
  end if;
  if exists (select 1 from pg_roles where rolname = 'authenticated') then
    revoke all on all tables in schema public from authenticated;
    revoke all on all sequences in schema public from authenticated;
    alter default privileges in schema public revoke all on tables from authenticated;
  end if;
end $$;

insert into schema_migrations (name) values ('0003_security.sql');

-- ===== 0004_trust_states.sql
-- Trust states, documented policy searches, richer change history, and the revised index quality gate.

-- 1. Public trust state on every rule version. Separate from the internal workflow status.
alter table rule_versions add column trust_state text not null default 'NEEDS_REVIEW' check (trust_state in (
  'VERIFIED_TO_OFFICIAL_SOURCE',        -- an official primary source was located and checked
  'PUBLIC_POLICY_NOT_LOCATED',          -- public sources were searched; no school/district-specific policy located (does not mean none exists)
  'PENDING_INSTITUTION_CONFIRMATION',   -- needs direct confirmation from the institution
  'NEEDS_REVIEW',                       -- a source exists but interpretation, currency or applicability needs more review
  'SUPERSEDED'));                       -- kept for history, no longer current
-- How the check was done. 'human_review' may only be set when a person actually reviewed it.
alter table rule_versions add column review_method text not null default 'automated_extraction' check (review_method in (
  'automated_extraction','raw_source_text','visual_source_check','human_review'));
alter table rule_versions add column review_note text;
alter table rule_versions add column short_answer text;   -- one-line answer for the quick-answer layer
-- Quick-answer status. Stored on the rule so the top-of-page answer is a database fact, not template logic.
alter table rule_versions add column quick_status text check (quick_status in
  ('YES','NO','DEPENDS','CHECK_FIRST','NOT_PUBLICLY_SPECIFIED'));

alter table rule_version_sources drop constraint rule_version_sources_quote_check_check;
alter table rule_version_sources add constraint rule_version_sources_quote_check_check check (quote_check in
  ('machine_extracted','machine_confirmed_twice','machine_raw_text','visual_source_check','human_checked'));

-- 2. Policy searches: what we looked for, where, when, and what we did or did not find.
--    "Not located" is a statement about our search, never a claim that no policy exists.
create table policy_searches (
  id                       serial primary key,
  institution_id           int references institutions(id) on delete cascade,
  district_id              int references school_districts(id),
  governing_body_id        int references governing_bodies(id),
  subject                  text not null default 'nil_policy',
  public_policy_found      boolean not null,
  search_date              date not null,
  locations_checked        text[] not null,            -- pages and documents reviewed
  locations_unreachable    text[],                     -- documents that exist but could not be opened
  institution_confirmation boolean not null default false,
  confirmed_on             date,
  searched_by              text not null,
  notes                    text
);

-- 3. Change history that can show previous and current rule text.
alter table rule_change_log add column previous_text text;
alter table rule_change_log add column current_text text;
alter table rule_change_log add column effective_on date;

-- 4. Index quality gate, revised. Not a word count. Not weakened.
drop view v_page_quality_gate;
create view v_page_quality_gate as
with ir as (select * from v_institution_rules),
agg as (
  select
    i.id as institution_id,
    exists (select 1 from institution_governing_bodies g where g.institution_id = i.id) as governing_body_identified,
    exists (select 1 from ir where ir.institution_id = i.id and ir.topic_slug = 'nil-allowed') as current_status_established,
    (select count(*) from ir where ir.institution_id = i.id) as rule_count,
    -- accuracy: rules still under review or waiting on the school
    (select count(*) from ir join rule_versions v on v.id = ir.rule_version_id where ir.institution_id = i.id
        and v.trust_state in ('NEEDS_REVIEW','PENDING_INSTITUTION_CONFIRMATION')) as rules_needing_review,
    (select count(*) from ir where ir.institution_id = i.id
        and not exists (select 1 from rule_version_sources rs join sources s on s.id = rs.source_id
                        where rs.rule_version_id = ir.rule_version_id and s.is_primary)) as rules_without_primary_source,
    (select count(distinct ir.topic_slug) from ir where ir.institution_id = i.id and ir.answer <> 'not_addressed') as topics_answered,
    (select count(*) from ir where ir.institution_id = i.id and ir.scope_type in ('district','institution')
        and ir.answer <> 'not_addressed') as school_level_rules,
    -- school-specific research: a documented search of at least three public locations
    exists (select 1 from policy_searches ps where ps.institution_id = i.id and array_length(ps.locations_checked, 1) >= 3) as school_research_documented,
    exists (select 1 from school_nil_policies p where p.institution_id = i.id and p.policy_status = 'published') as school_policy_published,
    exists (select 1 from policy_searches ps where ps.institution_id = i.id and ps.institution_confirmation) as institution_confirmed,
    (select count(*) from nil_programs n where n.institution_id = i.id) as program_count,
    exists (select 1 from school_contacts c where c.institution_id = i.id and c.show_on_page
              and c.verification_status in ('verified','school_confirmed')) as contact_verified,
    (select count(*) from scenarios sc
       where (sc.applies_to = 'both' or sc.applies_to = i.institution_type)
         and not exists (select 1 from scenario_rule_topics srt
                         where srt.scenario_id = sc.id and srt.role = 'governs'
                           and not exists (select 1 from ir where ir.institution_id = i.id
                                           and ir.rule_topic_id = srt.rule_topic_id and ir.answer <> 'not_addressed'))) as scenarios_answered,
    (select max(ir.last_verified_on) from ir where ir.institution_id = i.id) as last_verified_on,
    exists (select 1 from conflicts cf join ir on ir.rule_id = cf.rule_id
            where ir.institution_id = i.id and cf.status = 'open' and cf.severity = 'high') as open_high_conflict
  from institutions i
)
select
  p.id as page_id, p.path, p.page_type, a.*,
  (p.title is not null and p.meta_description is not null and p.h1 is not null) as meta_complete,
  p.human_approved,
  a.governing_body_identified                               as chk_governing_body,
  a.current_status_established                              as chk_current_status,
  (a.rule_count > 0 and a.rules_needing_review = 0)         as chk_rules_verified,
  (a.rule_count > 0 and a.rules_without_primary_source = 0) as chk_sources_attached,
  (a.topics_answered >= 8)                                  as chk_matrix_populated,
  a.school_research_documented                              as chk_school_info_checked,
  -- thin-content guard: the page must hold school-level facts the state hub does not.
  -- A documented "nothing located" search does not count; a school confirmation does.
  ((a.school_level_rules + a.program_count
     + case when a.school_policy_published then 1 else 0 end
     + case when a.contact_verified then 1 else 0 end
     + case when a.institution_confirmed then 1 else 0 end) >= 3) as chk_school_specific_value,
  a.contact_verified                                        as chk_contact_checked,
  (a.scenarios_answered >= 5)                               as chk_scenarios_answered,
  (a.last_verified_on is not null)                          as chk_last_verified,
  (not a.open_high_conflict)                                as chk_no_open_conflict,
  case when
        a.governing_body_identified and a.current_status_established
    and a.rule_count > 0 and a.rules_needing_review = 0 and a.rules_without_primary_source = 0
    and a.topics_answered >= 8 and a.school_research_documented
    and (a.school_level_rules + a.program_count
          + case when a.school_policy_published then 1 else 0 end
          + case when a.contact_verified then 1 else 0 end
          + case when a.institution_confirmed then 1 else 0 end) >= 3
    and a.contact_verified and a.scenarios_answered >= 5 and a.last_verified_on is not null
    and not a.open_high_conflict
    and p.title is not null and p.meta_description is not null and p.h1 is not null
    and p.human_approved and p.index_override is null
  then 'index' else 'noindex' end as index_status
from pages p
join agg a on a.institution_id = p.institution_id
where p.page_type in ('college_hub','high_school_hub');
alter view v_page_quality_gate set (security_invoker = true);
alter table policy_searches enable row level security;

-- 5. Quick-answer layer: which scenarios appear in the top "Just tell me what I can do" block.
alter table scenarios add column is_quick boolean not null default false;

insert into schema_migrations (name) values ('0004_trust_states.sql');

-- ===== 0005_central_review.sql
-- Central human review. A person reviews a rule version once; every page that inherits the rule inherits the review.
-- Page-level review is limited to what is truly page-specific: the school's own facts and the editorial sign-off.

-- 1. Record a human review on the canonical rule version. Only ever call this for a review a person actually did.
create or replace function record_human_review(p_rule_slug text, p_reviewer text, p_note text default null, p_on date default current_date)
returns int language plpgsql as $$
declare v_id int; n int;
begin
  if coalesce(trim(p_reviewer), '') = '' then raise exception 'reviewer name is required'; end if;
  select v.id into v_id from rule_versions v join rules r on r.id = v.rule_id where r.slug = p_rule_slug and v.is_current;
  if v_id is null then raise exception 'no current version for rule %', p_rule_slug; end if;
  update rule_versions set review_method = 'human_review', last_verified_on = p_on, verified_by = p_reviewer, verification_status = 'verified' where id = v_id;
  insert into verification_events (entity_type, entity_id, status, method, verified_on, verified_by, notes)
    values ('rule_version', v_id, 'human_reviewed', 'second_checker', p_on, p_reviewer, p_note);
  select count(distinct p.id) into n from v_institution_rules ir join pages p on p.institution_id = ir.institution_id where ir.rule_version_id = v_id;
  return n;   -- how many school pages inherited this one review
end $$;

-- 2. Editorial sign-off for one page.
create or replace function approve_page(p_path text, p_approver text, p_on date default current_date)
returns text language plpgsql as $$
declare st text;
begin
  if coalesce(trim(p_approver), '') = '' then raise exception 'approver name is required'; end if;
  update pages set human_approved = true, approved_by = p_approver, approved_on = p_on where path = p_path;
  if not found then raise exception 'no page at %', p_path; end if;
  select index_status into st from v_page_quality_gate where path = p_path;
  return coalesce(st, 'not a school hub');
end $$;

-- Not callable through the public API.
revoke all on function record_human_review(text, text, text, date) from public;
revoke all on function approve_page(text, text, date) from public;

-- 3. The gate now requires a recorded human review on every rule a page inherits (before: on at least one).
drop view v_page_quality_gate;
create view v_page_quality_gate as
with ir as (select * from v_institution_rules),
agg as (
  select
    i.id as institution_id,
    exists (select 1 from institution_governing_bodies g where g.institution_id = i.id) as governing_body_identified,
    exists (select 1 from ir where ir.institution_id = i.id and ir.topic_slug = 'nil-allowed') as current_status_established,
    (select count(*) from ir where ir.institution_id = i.id) as rule_count,
    -- accuracy: rules still under review or waiting on the school
    (select count(*) from ir join rule_versions v on v.id = ir.rule_version_id where ir.institution_id = i.id
        and v.trust_state in ('NEEDS_REVIEW','PENDING_INSTITUTION_CONFIRMATION')) as rules_needing_review,
    (select count(*) from ir where ir.institution_id = i.id
        and not exists (select 1 from rule_version_sources rs join sources s on s.id = rs.source_id
                        where rs.rule_version_id = ir.rule_version_id and s.is_primary)) as rules_without_primary_source,
    (select count(distinct ir.topic_slug) from ir where ir.institution_id = i.id and ir.answer <> 'not_addressed') as topics_answered,
    (select count(*) from ir where ir.institution_id = i.id and ir.scope_type in ('district','institution')
        and ir.answer <> 'not_addressed') as school_level_rules,
    -- school-specific research: a documented search of at least three public locations
    exists (select 1 from policy_searches ps where ps.institution_id = i.id and array_length(ps.locations_checked, 1) >= 3) as school_research_documented,
    exists (select 1 from school_nil_policies p where p.institution_id = i.id and p.policy_status = 'published') as school_policy_published,
    exists (select 1 from policy_searches ps where ps.institution_id = i.id and ps.institution_confirmation) as institution_confirmed,
    (select count(*) from nil_programs n where n.institution_id = i.id) as program_count,
    exists (select 1 from school_contacts c where c.institution_id = i.id and c.show_on_page
              and c.verification_status in ('verified','school_confirmed')) as contact_verified,
    (select count(*) from scenarios sc
       where (sc.applies_to = 'both' or sc.applies_to = i.institution_type)
         and not exists (select 1 from scenario_rule_topics srt
                         where srt.scenario_id = sc.id and srt.role = 'governs'
                           and not exists (select 1 from ir where ir.institution_id = i.id
                                           and ir.rule_topic_id = srt.rule_topic_id and ir.answer <> 'not_addressed'))) as scenarios_answered,
    (select max(ir.last_verified_on) from ir where ir.institution_id = i.id) as last_verified_on,
    -- human review is recorded once on the rule version and inherited by every page under it
    (select count(*) from ir join rule_versions v on v.id = ir.rule_version_id where ir.institution_id = i.id
        and (v.review_method <> 'human_review' or v.last_verified_on is null)) as rules_without_human_review,
    exists (select 1 from conflicts cf join ir on ir.rule_id = cf.rule_id
            where ir.institution_id = i.id and cf.status = 'open' and cf.severity = 'high') as open_high_conflict
  from institutions i
)
select
  p.id as page_id, p.path, p.page_type, a.*,
  (p.title is not null and p.meta_description is not null and p.h1 is not null) as meta_complete,
  p.human_approved,
  a.governing_body_identified                               as chk_governing_body,
  a.current_status_established                              as chk_current_status,
  (a.rule_count > 0 and a.rules_needing_review = 0)         as chk_rules_verified,
  (a.rule_count > 0 and a.rules_without_primary_source = 0) as chk_sources_attached,
  (a.topics_answered >= 8)                                  as chk_matrix_populated,
  a.school_research_documented                              as chk_school_info_checked,
  -- thin-content guard: the page must hold school-level facts the state hub does not.
  -- A documented "nothing located" search does not count; a school confirmation does.
  ((a.school_level_rules + a.program_count
     + case when a.school_policy_published then 1 else 0 end
     + case when a.contact_verified then 1 else 0 end
     + case when a.institution_confirmed then 1 else 0 end) >= 3) as chk_school_specific_value,
  a.contact_verified                                        as chk_contact_checked,
  (a.scenarios_answered >= 5)                               as chk_scenarios_answered,
  (a.rule_count > 0 and a.rules_without_human_review = 0)                          as chk_last_verified,
  (not a.open_high_conflict)                                as chk_no_open_conflict,
  case when
        a.governing_body_identified and a.current_status_established
    and a.rule_count > 0 and a.rules_needing_review = 0 and a.rules_without_primary_source = 0
    and a.topics_answered >= 8 and a.school_research_documented
    and (a.school_level_rules + a.program_count
          + case when a.school_policy_published then 1 else 0 end
          + case when a.contact_verified then 1 else 0 end
          + case when a.institution_confirmed then 1 else 0 end) >= 3
    and a.contact_verified and a.scenarios_answered >= 5 and a.rules_without_human_review = 0
    and not a.open_high_conflict
    and p.title is not null and p.meta_description is not null and p.h1 is not null
    and p.human_approved and p.index_override is null
  then 'index' else 'noindex' end as index_status
from pages p
join agg a on a.institution_id = p.institution_id
where p.page_type in ('college_hub','high_school_hub');
alter view v_page_quality_gate set (security_invoker = true);

-- 4. Review queue: each rule once, with the number of pages one review unlocks.
create view v_review_queue as
select r.slug as rule_slug, r.scope_type, coalesce(gb.short_name, st.name || ' law', d.name, i.short_name, i.name) as issuer,
       t.label as topic, v.answer, v.trust_state, v.review_method, v.last_verified_on, v.verified_by,
       (select count(distinct p.id) from v_institution_rules ir join pages p on p.institution_id = ir.institution_id where ir.rule_version_id = v.id) as pages_inheriting
from rules r join rule_versions v on v.rule_id = r.id and v.is_current
join rule_topics t on t.id = r.rule_topic_id
left join governing_bodies gb on gb.id = r.governing_body_id
left join states st on st.id = r.state_id and r.scope_type = 'state'
left join school_districts d on d.id = r.district_id and r.scope_type = 'district'
left join institutions i on i.id = r.institution_id and r.scope_type = 'institution'
where r.status = 'active';
alter view v_review_queue set (security_invoker = true);
do $$ begin
  if exists (select 1 from pg_roles where rolname = 'anon') then
    revoke all on function record_human_review(text, text, text, date) from anon, authenticated;
    revoke all on function approve_page(text, text, date) from anon, authenticated;
  end if;
end $$;

insert into schema_migrations (name) values ('0005_central_review.sql');

