insert into rules (slug, rule_topic_id, scope_type, governing_body_id, applies_to) values ('fhsaa-school-staff', (select id from rule_topics where slug = 'school-staff-involvement'), 'governing_body', (select id from governing_bodies where slug = 'fhsaa'), 'high_school');
insert into rule_versions (rule_id, version_no, answer, summary, citation, verification_status, trust_state, review_method, quick_status, short_answer) values ((select id from rules where slug = 'fhsaa-school-staff'), 1, 'no', 'No. School employees, athletic department staff and representatives of the school''s athletic interests may not form, direct, offer, provide or otherwise take part in NIL activity.', 'FHSAA Bylaw 9.10.4.5', 'researched', 'VERIFIED_TO_OFFICIAL_SOURCE', 'visual_source_check', 'NO', 'No. School employees and athletic staff cannot take part in NIL deals.');
insert into rule_version_sources (rule_version_id, source_id, locator, quote, quote_check, checked_on, checked_by) values ((select v.id from rule_versions v join rules r on r.id = v.rule_id where r.slug = 'fhsaa-school-staff' and v.is_current), (select id from sources where slug = 'fhsaa-bylaw-9-9-sbe-2024'), 'Bylaw 9.9.4.5', 'No school employee, athletic department staff member, or representative of a school''s athletic interests as defined in Bylaw 1.4.17 (a-e), may form, direct, offer, provide, or otherwise engage in any activity outlined in FHSAA Bylaw 9.9. Representatives of a school''s athletic interests as defined in Bylaw 1.4.17(f) are subject to the prohibitions included in 9.9.4.2 and 9.9.4.4(i).', 'visual_source_check', '2026-10-03', 'Claude (automated source research)');
insert into rule_version_sources (rule_version_id, source_id, locator, quote, quote_check, checked_on, checked_by) values ((select v.id from rule_versions v join rules r on r.id = v.rule_id where r.slug = 'fhsaa-school-staff' and v.is_current), (select id from sources where slug = 'fhsaa-handbook-2026-27'), 'Bylaw 9.10 (numbered 9.9 before 2026-27), pages 30 to 31', NULL, 'machine_raw_text', '2026-10-03', 'Claude (automated source research)');
