insert into rules (slug, rule_topic_id, scope_type, governing_body_id, applies_to) values ('fhsaa-boosters', (select id from rule_topics where slug = 'boosters'), 'governing_body', (select id from governing_bodies where slug = 'fhsaa'), 'high_school');
insert into rule_versions (rule_id, version_no, answer, summary, conditions, citation, verification_status, trust_state, review_method, quick_status, short_answer) values ((select id from rules where slug = 'fhsaa-boosters'), 1, 'no', 'No. A member of a school''s athletic booster organization counts as a representative of the school''s athletic interests, and those representatives may not engage in NIL activity. The same definition covers volunteers and immediate relatives of coaches.', 'Bylaw 1.4.17 lists six groups. Members of a booster organization are group (e), so the full bar applies to them. Group (f), people and businesses that donate to or help promote the athletic program, is treated differently: the bylaw applies only the NIL collective prohibitions to them. Groups (a) and (b) are student-athletes and their own families, and the bylaw does not explain how the bar is meant to apply to them. Ask your athletic director if a deal involves a teammate''s or relative''s business.', 'FHSAA Bylaws 9.10.4.5 and 1.4.17 (a)-(e)', 'researched', 'VERIFIED_TO_OFFICIAL_SOURCE', 'visual_source_check', 'NO', 'No. Booster club members count as representatives of the school''s athletic interests.');
insert into rule_version_sources (rule_version_id, source_id, locator, quote, quote_check, checked_on, checked_by) values ((select v.id from rule_versions v join rules r on r.id = v.rule_id where r.slug = 'fhsaa-boosters' and v.is_current), (select id from sources where slug = 'fhsaa-handbook-2026-27'), 'Bylaw 1.4.17 (a) to (f), page 8 area', '(e) A member of an athletic booster organization of that school; (f) A person, business, organization, or group that makes financial or in-kind contributions to the athletic department or that is otherwise involved in promoting the school''s interscholastic athletic program.', 'machine_raw_text', '2026-10-03', 'Claude (automated source research)');
insert into rule_version_sources (rule_version_id, source_id, locator, quote, quote_check, checked_on, checked_by) values ((select v.id from rule_versions v join rules r on r.id = v.rule_id where r.slug = 'fhsaa-boosters' and v.is_current), (select id from sources where slug = 'fhsaa-handbook-2026-27'), 'Bylaw 9.10.4.5', 'No school employee, athletic department staff member, or representative of a school''s athletic interests as defined in Bylaw 1.4.17 (a-e), may form, direct, offer, provide, or otherwise engage in any activity outlined in FHSAA Bylaw 9.9. Representatives of a school''s athletic interests as defined in Bylaw 1.4.17(f) are subject to the prohibitions included in 9.9.4.2 and 9.9.4.4(i).', 'machine_raw_text', '2026-10-03', 'Claude (automated source research)');
