insert into disclosure_requirements (rule_version_id, what, recipient, deadline_text, deadline_business_days, form_name, form_url) values ((select v.id from rule_versions v join rules r on r.id = v.rule_id where r.slug = 'fhsaa-disclosure' and v.is_current), 'Form GA1 (Affidavit of Compliance), naming the other party to the NIL agreement and signed by the student and a parent or legal guardian', 'Your school''s athletic director, who completes Section B. A copy goes to FHSAA.', 'Within five business days of signing an NIL agreement', 5, 'FHSAA Form GA1', 'https://s3.amazonaws.com/fhsaa.org/documents/2024/10/2/GA1_Affidavit_of_Amateurism_10124.pdf');
