insert into rules (slug, rule_topic_id, scope_type, governing_body_id, applies_to) values ('ncaa-school-payments', (select id from rule_topics where slug = 'school-payments'), 'governing_body', (select id from governing_bodies where slug = 'ncaa'), 'college');
insert into rule_versions (rule_id, version_no, answer, summary, conditions, citation, verification_status, trust_state, review_method) values ((select id from rules where slug = 'ncaa-school-payments'), 1, 'yes_with_conditions', 'Yes. NCAA rules let a school make direct payments to athletes within the annual benefits cap, and the College Sports Commission says schools can enter NIL deals directly with athletes. Those deals are reported by the school and do not go into NIL Go.', 'The cap is about $21.58 million per school for 2026-27.', 'NCAA Division I Bylaw 16.13.1; CSC FAQ', 'researched', 'VERIFIED_TO_OFFICIAL_SOURCE', 'raw_source_text');
insert into rule_version_sources (rule_version_id, source_id, locator, quote, quote_check, checked_on, checked_by) values ((select v.id from rule_versions v join rules r on r.id = v.rule_id where r.slug = 'ncaa-school-payments' and v.is_current), (select id from sources where slug = 'ncaa-d1-manual-2026-27'), 'Bylaw 16.13.1', 'An institution may provide direct payments, benefits and expenses to a student-athlete as specified in this section, provided the aggregate value provided by (or on behalf of) the institution does not exceed the value of the applicable period’s benefits cap and the written agreement does not provide for payments to a third party on a student-athlete’s behalf.', 'machine_raw_text', '2026-10-03', 'Claude (automated source research)');
insert into rule_version_sources (rule_version_id, source_id, locator, quote, quote_check, checked_on, checked_by) values ((select v.id from rule_versions v join rules r on r.id = v.rule_id where r.slug = 'ncaa-school-payments' and v.is_current), (select id from sources where slug = 'csc-faq'), 'What is the revenue share cap?', 'The cap for the 2026-27 academic year is approximately $21.58 million per school, up from $20.5 million during the 2025-26 academic year. ... Yes. Those deals are reported by the school via the CAPS platform and subject to the revenue sharing cap. ... Payment directly from the student-athlete’s institution is not considered a third-party NIL deal and does not need to be reported in NIL Go.', 'machine_raw_text', '2026-10-03', 'Claude (automated source research)');
insert into verification_events (entity_type, entity_id, status, method, verified_on, verified_by, notes) values ('rule_version', (select v.id from rule_versions v join rules r on r.id = v.rule_id where r.slug = 'ncaa-school-payments' and v.is_current), 'VERIFIED_TO_OFFICIAL_SOURCE', 'automated_fetch', '2026-10-03', 'Claude (automated source research)', 'Full page text read from the official site by Claude. Not a human review.');
insert into rules (slug, rule_topic_id, scope_type, governing_body_id, applies_to) values ('ncaa-school-staff', (select id from rule_topics where slug = 'school-staff-involvement'), 'governing_body', (select id from governing_bodies where slug = 'ncaa'), 'college');
insert into rule_versions (rule_id, version_no, answer, summary, conditions, citation, verification_status, trust_state, review_method, quick_status, short_answer) values ((select id from rules where slug = 'ncaa-school-staff'), 1, 'yes_with_conditions', 'Yes, within limits. A school may act as a marketing agent for an athlete on third-party NIL deals. A school may not guarantee a third-party deal, and the payor must attest that the school did not direct it to make the deal and that it funded the payment itself.', 'A June 2025 NCAA question and answer document adds that a school may help identify or facilitate a deal when the third party funds the whole payment. That document predates the current Manual.', 'NCAA Division I Bylaws 22.1.1, 22.1.1.1 and 22.2.3', 'researched', 'VERIFIED_TO_OFFICIAL_SOURCE', 'raw_source_text', 'DEPENDS', 'A school may help find or facilitate a deal that a third party fully funds. It may not guarantee one.');
insert into rule_version_sources (rule_version_id, source_id, locator, quote, quote_check, checked_on, checked_by) values ((select v.id from rule_versions v join rules r on r.id = v.rule_id where r.slug = 'ncaa-school-staff' and v.is_current), (select id from sources where slug = 'ncaa-d1-manual-2026-27'), 'Bylaws 22.1.1(b), 22.1.1.1', 'Act as a marketing agent for a student-athlete with respect to noninstitutional name, image or likeness contracts. ... An institution shall not provide a written or oral guarantee of a third-party NIL contract or payment. ... (c) That the noninstitutional payor was not directed by an institution to enter into the contract or payment terms with the student-athlete; and (d) That the noninstitutional payor has self-funded the payment to the student-athlete.', 'machine_raw_text', '2026-10-03', 'Claude (automated source research)');
insert into rule_version_sources (rule_version_id, source_id, locator, quote, quote_check, checked_on, checked_by) values ((select v.id from rule_versions v join rules r on r.id = v.rule_id where r.slug = 'ncaa-school-staff' and v.is_current), (select id from sources where slug = 'ncaa-house-qa-2025-06'), 'Question E3', 'Yes, provided the third party is self-funding the entire payment outlined in the NIL contract.', 'machine_extracted', '2026-10-03', 'Claude (automated source research)');
insert into verification_events (entity_type, entity_id, status, method, verified_on, verified_by, notes) values ('rule_version', (select v.id from rule_versions v join rules r on r.id = v.rule_id where r.slug = 'ncaa-school-staff' and v.is_current), 'VERIFIED_TO_OFFICIAL_SOURCE', 'automated_fetch', '2026-10-03', 'Claude (automated source research)', 'Full page text read from the official site by Claude. Not a human review.');
insert into rules (slug, rule_topic_id, scope_type, governing_body_id, applies_to) values ('ncaa-collectives', (select id from rule_topics where slug = 'collectives'), 'governing_body', (select id from governing_bodies where slug = 'ncaa'), 'college');
insert into rule_versions (rule_id, version_no, answer, summary, citation, verification_status, trust_state, review_method) values ((select id from rules where slug = 'ncaa-collectives'), 1, 'yes_with_conditions', 'Yes, but deals with a collective or any other "associated entity" must be for a valid business purpose (promoting goods or services sold to the public for profit), at rates in line with what similarly situated people with comparable NIL value, who are not athletes or recruits of that school, are paid. Raising money to induce athletes to attend a school does not qualify.', 'NCAA Division I Bylaws 22.02.1 and 22.1.3', 'researched', 'VERIFIED_TO_OFFICIAL_SOURCE', 'raw_source_text');
insert into rule_version_sources (rule_version_id, source_id, locator, quote, quote_check, checked_on, checked_by) values ((select v.id from rule_versions v join rules r on r.id = v.rule_id where r.slug = 'ncaa-collectives' and v.is_current), (select id from sources where slug = 'ncaa-d1-manual-2026-27'), 'Bylaw 22.1.3', 'An associated entity or individual shall not enter into an agreement with or provide payment to a prospective student-athlete or student-athlete unless the agreement or payment terms, as determined by the name, image and likeness clearinghouse, are for a valid business purpose related to the promotion or endorsement of goods or services provided to the general public for profit, with compensation at rates and terms commensurate with compensation paid to similarly situated individuals with comparable name, image and likeness value who are not prospective student-athletes or student-athletes of the institution. Raising money to induce student-athletes to attend or participate in intercollegiate athletics at an institution does not satisfy the valid business purpose requirement for making NIL payments to student-athletes.', 'machine_raw_text', '2026-10-03', 'Claude (automated source research)');
insert into verification_events (entity_type, entity_id, status, method, verified_on, verified_by, notes) values ('rule_version', (select v.id from rule_versions v join rules r on r.id = v.rule_id where r.slug = 'ncaa-collectives' and v.is_current), 'VERIFIED_TO_OFFICIAL_SOURCE', 'automated_fetch', '2026-10-03', 'Claude (automated source research)', 'Full page text read from the official site by Claude. Not a human review.');
insert into rules (slug, rule_topic_id, scope_type, governing_body_id, applies_to) values ('ncaa-boosters', (select id from rule_topics where slug = 'boosters'), 'governing_body', (select id from governing_bodies where slug = 'ncaa'), 'college');
insert into rule_versions (rule_id, version_no, answer, summary, citation, verification_status, trust_state, review_method, quick_status, short_answer) values ((select id from rules where slug = 'ncaa-boosters'), 1, 'yes_with_conditions', 'Yes, with review. Anyone who has given more than $50,000 in their lifetime to the school or its collective is an "associated individual", so deals with them face the valid business purpose and compensation tests.', 'NCAA Division I Bylaws 22.02.2 and 22.1.3', 'researched', 'VERIFIED_TO_OFFICIAL_SOURCE', 'raw_source_text', 'DEPENDS', 'Yes, but deals with major donors get extra review in NIL Go.');
insert into rule_version_sources (rule_version_id, source_id, locator, quote, quote_check, checked_on, checked_by) values ((select v.id from rule_versions v join rules r on r.id = v.rule_id where r.slug = 'ncaa-boosters' and v.is_current), (select id from sources where slug = 'ncaa-d1-manual-2026-27'), 'Bylaw 22.02.2(b)', 'An individual who directly or indirectly (including contributions by an affiliated entity or family member) has contributed more than $50,000 during the individual’s lifetime to an institution or to an associated entity defined in 22.02.1-(a)', 'machine_raw_text', '2026-10-03', 'Claude (automated source research)');
insert into verification_events (entity_type, entity_id, status, method, verified_on, verified_by, notes) values ('rule_version', (select v.id from rule_versions v join rules r on r.id = v.rule_id where r.slug = 'ncaa-boosters' and v.is_current), 'VERIFIED_TO_OFFICIAL_SOURCE', 'automated_fetch', '2026-10-03', 'Claude (automated source research)', 'Full page text read from the official site by Claude. Not a human review.');
insert into rules (slug, rule_topic_id, scope_type, governing_body_id, applies_to) values ('ncaa-agents', (select id from rule_topics where slug = 'agents'), 'governing_body', (select id from governing_bodies where slug = 'ncaa'), 'college');
insert into rule_versions (rule_id, version_no, answer, summary, citation, verification_status, trust_state, review_method, quick_status, short_answer) values ((select id from rules where slug = 'ncaa-agents'), 1, 'yes', 'Yes. NCAA rules allow professional services, including agent representation, for NIL activities.', 'NCAA Division I Bylaw 22.3.1', 'researched', 'VERIFIED_TO_OFFICIAL_SOURCE', 'raw_source_text', 'YES', 'Yes. NCAA rules allow agent representation for NIL.');
insert into rule_version_sources (rule_version_id, source_id, locator, quote, quote_check, checked_on, checked_by) values ((select v.id from rule_versions v join rules r on r.id = v.rule_id where r.slug = 'ncaa-agents' and v.is_current), (select id from sources where slug = 'ncaa-d1-manual-2026-27'), 'Bylaw 22.3.1', 'An individual may use professional services, including agent representation, for the purpose of name, image and likeness activities.', 'machine_raw_text', '2026-10-03', 'Claude (automated source research)');
insert into verification_events (entity_type, entity_id, status, method, verified_on, verified_by, notes) values ('rule_version', (select v.id from rule_versions v join rules r on r.id = v.rule_id where r.slug = 'ncaa-agents' and v.is_current), 'VERIFIED_TO_OFFICIAL_SOURCE', 'automated_fetch', '2026-10-03', 'Claude (automated source research)', 'Full page text read from the official site by Claude. Not a human review.');
insert into rules (slug, rule_topic_id, scope_type, governing_body_id, applies_to) values ('ncaa-disclosure', (select id from rule_topics where slug = 'disclosure-required'), 'governing_body', (select id from governing_bodies where slug = 'ncaa'), 'college');
insert into rule_versions (rule_id, version_no, answer, summary, conditions, citation, effective_date, verification_status, trust_state, review_method, quick_status, short_answer) values ((select id from rules where slug = 'ncaa-disclosure'), 1, 'yes', 'Yes. Every Division I athlete must report all third-party NIL deals worth $600 or more in total to NIL Go within five business days of signing or agreeing to payment terms. Multiple deals or payments from the same or related payor count together, and non-cash benefits count toward the $600.', 'One representative may enter the deal, but the athlete must submit it.', 'NCAA Division I Bylaws 22.2.2 and 22.2.2.2; CSC FAQ and NIL Go page', '2025-07-01', 'researched', 'VERIFIED_TO_OFFICIAL_SOURCE', 'raw_source_text', 'DEPENDS', 'Deals worth $600 or more go into NIL Go within five business days.');
insert into rule_version_sources (rule_version_id, source_id, locator, quote, quote_check, checked_on, checked_by) values ((select v.id from rule_versions v join rules r on r.id = v.rule_id where r.slug = 'ncaa-disclosure' and v.is_current), (select id from sources where slug = 'ncaa-d1-manual-2026-27'), 'Bylaws 22.2.2, 22.2.2.2', 'If an individual enters into multiple agreements or receives multiple payments from the same or substantially the same third party, including any affiliates or parties with common ownership, such activities must be reported if the aggregate value is $600 or more during the student-athlete’s period of eligibility. ... A student-athlete shall submit written documentation to the name, image and likeness clearinghouse within five business days of execution of a noninstitutional name, image or likeness contract or agreement to payment terms.', 'machine_raw_text', '2026-10-03', 'Claude (automated source research)');
insert into rule_version_sources (rule_version_id, source_id, locator, quote, quote_check, checked_on, checked_by) values ((select v.id from rule_versions v join rules r on r.id = v.rule_id where r.slug = 'ncaa-disclosure' and v.is_current), (select id from sources where slug = 'csc-faq'), 'What type of NIL deals must be reported in NIL Go?', 'All NCAA Division I student-athletes must report third-party NIL deals with compensation that equals or exceeds $600 (including contracts or payments with the potential to meet or exceed $600 via payment structures such as royalties or bonuses). Compensation includes both direct payments and other benefits such as free car leases, gym memberships, etc.', 'machine_raw_text', '2026-10-03', 'Claude (automated source research)');
insert into rule_version_sources (rule_version_id, source_id, locator, quote, quote_check, checked_on, checked_by) values ((select v.id from rule_versions v join rules r on r.id = v.rule_id where r.slug = 'ncaa-disclosure' and v.is_current), (select id from sources where slug = 'csc-nil-go'), 'How NIL Go Works', 'Student-athletes may each designate one representative to enter deals into NIL Go on their behalf, for submission by the student-athlete.', 'machine_raw_text', '2026-10-03', 'Claude (automated source research)');
insert into disclosure_requirements (rule_version_id, what, recipient, deadline_text, deadline_business_days, threshold_usd, platform_name, platform_url) values ((select v.id from rule_versions v join rules r on r.id = v.rule_id where r.slug = 'ncaa-disclosure' and v.is_current), 'Every third-party NIL deal worth $600 or more in total (cash and non-cash), with the contract or payment terms', 'NIL Go, the clearinghouse run by the College Sports Commission', 'Within five business days of signing or agreeing to payment terms', 5, 600, 'NIL Go', 'https://www.collegesportscommission.org/nil/');
insert into verification_events (entity_type, entity_id, status, method, verified_on, verified_by, notes) values ('rule_version', (select v.id from rule_versions v join rules r on r.id = v.rule_id where r.slug = 'ncaa-disclosure' and v.is_current), 'VERIFIED_TO_OFFICIAL_SOURCE', 'automated_fetch', '2026-10-03', 'Claude (automated source research)', 'Full page text read from the official site by Claude. Not a human review.');
insert into rules (slug, rule_topic_id, scope_type, governing_body_id, applies_to) values ('csc-deal-review', (select id from rule_topics where slug = 'deal-review'), 'governing_body', (select id from governing_bodies where slug = 'college-sports-commission'), 'college');
insert into rule_versions (rule_id, version_no, answer, summary, conditions, citation, effective_date, verification_status, change_note, trust_state, review_method) values ((select id from rules where slug = 'csc-deal-review'), 1, 'yes', 'Yes. NIL Go checks whether the payor is tied to the school. If it is, the deal must have a valid business purpose and pay within a reasonable range. Since July 1, 2026, associated deals of $600 to $15,000 skip the compensation-range review until the athlete has more than $50,000 in associated deals in an academic year. Deals come back Cleared, Not Cleared or Flagged.', 'Exempt deals must still be reported and still need a valid business purpose.', 'NCAA Division I Bylaw 22.2.4; CSC Memorandum of June 23, 2026', '2026-07-01', 'researched', 'Replaced the April 2026 policy, which exempted deals up to $2,500 until an athlete reached $15,000 in associated deals.', 'VERIFIED_TO_OFFICIAL_SOURCE', 'raw_source_text');
insert into rule_version_sources (rule_version_id, source_id, locator, quote, quote_check, checked_on, checked_by) values ((select v.id from rule_versions v join rules r on r.id = v.rule_id where r.slug = 'csc-deal-review' and v.is_current), (select id from sources where slug = 'csc-memo-2026-06-23'), 'Part I, Updated Enforcement Policy', 'the CSC will not subject deals valued between $600-$15,000 to RoC review unless and until a student-athlete has exceeded $50,000 in Associated deals in an academic year. ... This updates the prior policy, in effect since April 2026, that exempted deals up to $2,500 from RoC review unless and until a student-athlete reached $15,000 in Associated deals. ... All Associated deals still must be "for a valid business purpose related to the promotion or endorsement of goods or services provided to the general public for profit."', 'machine_extracted', '2026-10-03', 'Claude (automated source research)');
insert into rule_version_sources (rule_version_id, source_id, locator, quote, quote_check, checked_on, checked_by) values ((select v.id from rule_versions v join rules r on r.id = v.rule_id where r.slug = 'csc-deal-review' and v.is_current), (select id from sources where slug = 'ncaa-d1-manual-2026-27'), 'Bylaw 22.2.4', 'The name, image and likeness clearinghouse shall review all reported noninstitutional name, image and likeness contracts or payment terms submitted by student-athletes once all reporting requirements have been met (see Bylaw 22.2.2) to determine whether an associated entity or individual, including a noninstitutional payor, is involved.', 'machine_raw_text', '2026-10-03', 'Claude (automated source research)');
insert into rule_version_sources (rule_version_id, source_id, locator, quote, quote_check, checked_on, checked_by) values ((select v.id from rule_versions v join rules r on r.id = v.rule_id where r.slug = 'csc-deal-review' and v.is_current), (select id from sources where slug = 'csc-nil-go'), 'Deal Review and Outcomes', 'Cleared – The deal meets necessary requirements and can proceed. Not Cleared – The deal fails to meet necessary requirements. ... Flagged for Additional Review', 'machine_raw_text', '2026-10-03', 'Claude (automated source research)');
insert into verification_events (entity_type, entity_id, status, method, verified_on, verified_by, notes) values ('rule_version', (select v.id from rule_versions v join rules r on r.id = v.rule_id where r.slug = 'csc-deal-review' and v.is_current), 'VERIFIED_TO_OFFICIAL_SOURCE', 'automated_fetch', '2026-10-03', 'Claude (automated source research)', 'Full page text read from the official site by Claude. Not a human review.');
insert into rules (slug, rule_topic_id, scope_type, governing_body_id, applies_to) values ('ncaa-penalties', (select id from rule_topics where slug = 'penalties'), 'governing_body', (select id from governing_bodies where slug = 'ncaa'), 'college');
insert into rule_versions (rule_id, version_no, answer, summary, citation, verification_status, trust_state, review_method) values ((select id from rules where slug = 'ncaa-penalties'), 1, 'yes', 'Not reporting a deal within five business days, or carrying on with a deal that was not cleared, can cost eligibility. If a deal is not cleared, the athlete can revise and resubmit it, appeal, or return the payment.', 'NCAA Division I Bylaws 22.2.2.2, 22.2.4.2 and 23.2.5.1; CSC FAQ', 'researched', 'VERIFIED_TO_OFFICIAL_SOURCE', 'raw_source_text');
insert into rule_version_sources (rule_version_id, source_id, locator, quote, quote_check, checked_on, checked_by) values ((select v.id from rule_versions v join rules r on r.id = v.rule_id where r.slug = 'ncaa-penalties' and v.is_current), (select id from sources where slug = 'ncaa-d1-manual-2026-27'), 'Bylaws 22.2.4.2, 23.2.5.1', '(a) The contract or payment terms may be rescinded or revised and resubmitted; (b) An appeal of the decision may be submitted to the designated enforcement entity ...; or (c) The student-athlete may return the impermissible amount of payment received. ... The CSC may declare a student-athlete ineligible for participation in athletically related activities, including practice or competition.', 'machine_raw_text', '2026-10-03', 'Claude (automated source research)');
insert into rule_version_sources (rule_version_id, source_id, locator, quote, quote_check, checked_on, checked_by) values ((select v.id from rule_versions v join rules r on r.id = v.rule_id where r.slug = 'ncaa-penalties' and v.is_current), (select id from sources where slug = 'ncaa-d1-manual-2026-27'), 'Bylaw 22.2.2.2', 'Failure to report an agreement or payment within the five-day period may result in disciplinary action by the CSC, which may include rendering the student-athlete ineligible for future practice and competition (see Bylaw 23.3).', 'machine_raw_text', '2026-10-03', 'Claude (automated source research)');
