insert into rule_versions (rule_id, version_no, answer, summary, citation, verification_status, trust_state, review_method) values ((select id from rules where slug = 'ncaa-prospects-reporting'), 1, 'yes', 'Yes. An athlete enrolling at a Division I school must report third-party deals of $600 or more made since the first day of junior year of high school (or July 1, 2025, if later). The deadline is 14 days after enrolling full time or before the team''s first game, whichever comes first.', 'NCAA Division I Bylaws 22.2.2.5.1 and 22.2.2.5.3', 'researched', 'VERIFIED_TO_OFFICIAL_SOURCE', 'raw_source_text');
insert into rule_version_sources (rule_version_id, source_id, locator, quote, quote_check, checked_on, checked_by) values ((select v.id from rule_versions v join rules r on r.id = v.rule_id where r.slug = 'ncaa-prospects-reporting' and v.is_current), (select id from sources where slug = 'ncaa-d1-manual-2026-27'), 'Bylaws 22.2.2.5.1, 22.2.2.5.3', 'An incoming prospective student-athlete must report noninstitutional name, image and likeness contracts or payment terms not later than either 14 days after initial full-time enrollment at a Division I institution, or prior to the institution’s first scheduled contest against outside competition in the individual''s sport, whichever occurs first.', 'machine_raw_text', '2026-10-03', 'Claude (automated source research)');
insert into rule_version_sources (rule_version_id, source_id, locator, quote, quote_check, checked_on, checked_by) values ((select v.id from rule_versions v join rules r on r.id = v.rule_id where r.slug = 'ncaa-prospects-reporting' and v.is_current), (select id from sources where slug = 'ncaa-nil-page'), 'High school prospects planning to play Division I', 'Report threshold: all third-party NIL deals worth $600 or more since July 1, 2025 or starting your junior year of high school, whichever is later', 'machine_extracted', '2026-10-03', 'Claude (automated source research)');
