insert into rule_versions (rule_id, version_no, answer, summary, conditions, citation, verification_status, trust_state, review_method, quick_status, short_answer) values ((select id from rules where slug = 'uf-uniform'), 1, 'yes_with_conditions', 'Only for Gators sponsors. UF''s overview answers "Can I wear UF logos in my NIL deal?" this way: if the company is a sponsor of the Gators, yes; if not, you cannot promote it in Gators gear.', 'UF also says to avoid showing UF logos or team trademarks in your own ads unless you have approval.', 'UF, Overview of Gators NIL', 'researched', 'VERIFIED_TO_OFFICIAL_SOURCE', 'raw_source_text', 'DEPENDS', 'Only if the company is a Gators sponsor.');
insert into rule_version_sources (rule_version_id, source_id, locator, quote, quote_check, checked_on, checked_by) values ((select v.id from rule_versions v join rules r on r.id = v.rule_id where r.slug = 'uf-uniform' and v.is_current), (select id from sources where slug = 'uf-nil-overview'), 'Common Questions; Social Media and Content Creation', 'Can I wear UF logos in my NIL deal? Is the company a Sponsor of the Gators? If yes, of course! If no, then you cannot promote it in Gators Gear. ... Avoid showing any UF logos or team trademarks in those ads unless you’ve gotten the proper approval.', 'machine_raw_text', '2026-10-03', 'Claude (automated source research)');
