insert into rule_versions (rule_id, version_no, answer, summary, citation, verification_status, trust_state, review_method) values ((select id from rules where slug = 'uf-team-issued-gear'), 1, 'no', 'No. Athletes cannot sell, trade or give away for value any equipment or apparel issued by UF. Signing a jersey you bought yourself is fine.', 'UF, Overview of Gators NIL', 'researched', 'VERIFIED_TO_OFFICIAL_SOURCE', 'raw_source_text');
insert into rule_version_sources (rule_version_id, source_id, locator, quote, quote_check, checked_on, checked_by) values ((select v.id from rule_versions v join rules r on r.id = v.rule_id where r.slug = 'uf-team-issued-gear' and v.is_current), (select id from sources where slug = 'uf-nil-overview'), 'What you cannot do', 'You can autograph a photo of yourself or sign a jersey you buy on your own, but you cannot sell, trade, or give away for value any equipment or apparel issued by UF (e.g. your game jersey, helmet, team shoes, gear bag, etc.).', 'machine_raw_text', '2026-10-03', 'Claude (automated source research)');
