insert into rule_versions (rule_id, version_no, answer, summary, citation, verification_status, trust_state, review_method) values ((select id from rules where slug = 'uf-prohibited-categories'), 1, 'no', 'UF does not allow NIL agreements with gambling or sports wagering vendors, or with vendors associated with performance enhancing drugs, both as defined by the NCAA. No other category limits were found in UF''s published material.', 'UF, Overview of Gators NIL', 'researched', 'VERIFIED_TO_OFFICIAL_SOURCE', 'raw_source_text');
insert into rule_version_sources (rule_version_id, source_id, locator, quote, quote_check, checked_on, checked_by) values ((select v.id from rule_versions v join rules r on r.id = v.rule_id where r.slug = 'uf-prohibited-categories' and v.is_current), (select id from sources where slug = 'uf-nil-overview'), 'Prohibited vendors', 'Student-athletes will not be permitted to enter into NIL agreements with gambling/sports wagering vendors or vendors associated with athlete performance enhancing drugs, both as defined by the NCAA.', 'machine_raw_text', '2026-10-03', 'Claude (automated source research)');
