insert into rule_versions (rule_id, version_no, answer, summary, citation, verification_status, trust_state, review_method, review_note, quick_status, short_answer) values ((select id from rules where slug = 'uf-facilities'), 1, 'not_addressed', 'UF''s published NIL material does not say whether athletes can use UF facilities for sponsored shoots. Ask UAA Compliance before planning one.', 'UF, Overview of Gators NIL (no provision found)', 'needs_verification', 'PUBLIC_POLICY_NOT_LOCATED', 'automated_extraction', 'UF''s NIL overview page was read in full on October 3, 2026. It does not address facility use for NIL.', 'NOT_PUBLICLY_SPECIFIED', 'UF''s published NIL material does not say. Ask UAA Compliance first.');
